<template>
    <div class="root--tree">

        <ul class="media-tree">
            <li v-on:click.stop="folderSelected" :class="{ 'media-tree--active':folder.active }">

                <drop class="drop media-tree__item" @drop="handleDrop(folder, ...arguments)">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 85.04 56.69"><path d="M79.3 9.77H42.2a5.41 5.41 0 0 1-3.56-1.33L29.88.76a3.1 3.1 0 0 0-2-.76H3.54A3.49 3.49 0 0 0 0 3.42v47.73a5.66 5.66 0 0 0 5.74 5.54H79.3a5.64 5.64 0 0 0 5.7-5.54V15.32a5.64 5.64 0 0 0-5.7-5.55z"/></svg>
                    <span>{{ folder.name }}</span>
                </drop>

                <ul class="media-tree__items" v-if="folder.children && folder.children.length">
                    <MediaTreeItem v-for="child in folder.children" :key="child.id" v-bind:folder="child" />
                </ul>

            </li>
        </ul>

    </div>
</template>

<script>
    import  { mapState } from 'vuex'
    import MediaTreeItem from "./MediaTreeItem.vue"
    import {Drop} from "vue-drag-drop";

    export default {
        components: {
            MediaTreeItem,
            Drop
        },
        computed: {
            ...mapState([
                'folder'
            ])
        },
        methods: {
            folderSelected() {
                this.$store.dispatch('folderSelected', this.folder)
            },
            handleDrop(destinationFolder, transferData, nativeEvent) {
                console.log(destinationFolder)
                console.log(transferData);
                console.log(nativeEvent);
                // alert(`You dropped with data: ${JSON.stringify(data)}`);
                let payload = {
                    folder: destinationFolder,
                    item: transferData
                }
                this.$store.dispatch('moveItem', payload)
            }
        }
    }
</script>
